draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;

  // stick figure body
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // head
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50 - 20 * Math.sin(t), 20, 0, 2 * Math.PI);
  ctx.stroke();

  // arms
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 20);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 + 20);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 20);
  ctx.lineTo(W/2 + 30 + 20 * Math.sin(t), H/2 + 20);
  ctx.stroke();

  // legs
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 - 20 + 10 * Math.sin(t), H/2 + 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2 + 20 + 10 * Math.sin(t), H/2 + 50);
  ctx.stroke();

  ctx.restore();
}
